package com.hs.jxc.fin.report;

import com.hs.jxc.common.api.*;
import com.hs.jxc.fin.accounting.AccountingService;
import com.hs.jxc.sys.api.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

/** Symbolic configuration snapshot. Target IDs are newly allocated; balances and postings never cross. */
@Component
public class FinanceTemplateContributor implements TemplateStructureContributor {
 private final JdbcTemplate db;private final JsonCodec json;private final AccountingService accounting;
 public FinanceTemplateContributor(JdbcTemplate db,JsonCodec json,AccountingService accounting){this.db=db;this.json=json;this.accounting=accounting;}
 public int order(){return 10;}public String key(){return "finance-structure";}public String itemType(){return "FINANCE";}public String label(){return "科目、现金流、凭证字、映射和报表结构";}public boolean requiresReview(){return true;}
 private Long book(Access a,boolean required){var books=db.queryForList("SELECT id FROM fin_book WHERE country_id=? AND status='ACTIVE' ORDER BY id",Long.class,a.requireCountry());if(books.size()>1||required&&books.isEmpty())throw new ApiException(409,"SYS_CONFIG_MISSING","财务结构复制要求明确唯一的启用账套");return books.isEmpty()?null:books.getFirst();}
 public Map<String,Object> snapshot(Access a){
  var out=new LinkedHashMap<String,Object>();Long book=book(a,false);for(String key:List.of("accounts","cashflows","words","categoryMaps","mappings","reports"))out.put(key,new ArrayList<Map<String,Object>>());if(book==null)return out;
  out.put("accounts",db.queryForList("SELECT a.code,a.name,p.code AS parent_code,a.level,a.category,a.direction,a.is_leaf,a.fx_enabled,a.is_cash,a.is_bank,a.aux_types,a.reconcile_type,a.status FROM fin_account a LEFT JOIN fin_account p ON p.country_id=a.country_id AND p.book_id=a.book_id AND p.id=a.parent_id WHERE a.country_id=? AND a.book_id=? ORDER BY a.level,a.code",a.requireCountry(),book).stream().map(r->{var copy=new LinkedHashMap<>(r);copy.put("aux_types",json.read(r.get("aux_types").toString(),List.class));return copy;}).toList());
  out.put("cashflows",db.queryForList("SELECT code,name,category,direction,status FROM fin_cashflow_item WHERE country_id=? AND book_id=? ORDER BY code",a.requireCountry(),book));
  out.put("words",db.queryForList("SELECT code,name,number_rule,status FROM fin_voucher_word WHERE country_id=? AND book_id=? ORDER BY code",a.requireCountry(),book));
  out.put("categoryMaps",db.queryForList("SELECT c.code AS category_code,m.purpose,a.code AS account_code FROM fin_category_account_map m JOIN md_category c ON c.id=m.category_id JOIN fin_account a ON a.country_id=m.country_id AND a.book_id=m.book_id AND a.id=m.account_id WHERE m.country_id=? AND m.book_id=? ORDER BY c.code,m.purpose",a.requireCountry(),book));
  var mappings=new ArrayList<Map<String,Object>>();for(var template:db.queryForList("SELECT id,event_type,accounting_mode,no_voucher_reason FROM fin_mapping_template WHERE country_id=? AND book_id=? AND status='ACTIVE' ORDER BY event_type",a.requireCountry(),book)){
   var lines=new ArrayList<Map<String,Object>>();for(var raw:db.queryForList("SELECT * FROM fin_mapping_line WHERE country_id=? AND book_id=? AND template_id=? ORDER BY seq",a.requireCountry(),book,template.get("id"))){var line=new LinkedHashMap<String,Object>();var original=json.readMap(raw.get("account_rule").toString());var rule=new LinkedHashMap<String,Object>();for(String field:List.of("type","purpose","code","accountId"))if(original.containsKey(field))rule.put(field,original.get(field));if(rule.get("accountId")!=null){rule.put("code",code(a,book,"fin_account",Inputs.id(rule.remove("accountId"))));}line.put("direction",raw.get("direction"));line.put("accountRule",rule);line.put("amountExpr",raw.get("amount_expr"));line.put("auxMapping",json.readMap(raw.get("aux_mapping").toString()));line.put("summary",raw.get("summary_tpl"));line.put("cashflowCode",raw.get("cashflow_item_id")==null?null:code(a,book,"fin_cashflow_item",Inputs.id(raw.get("cashflow_item_id"))));lines.add(line);}
   var value=new LinkedHashMap<String,Object>();value.put("eventType",template.get("event_type"));value.put("accountingMode",template.get("accounting_mode"));value.put("noVoucherReason",template.get("no_voucher_reason"));value.put("lines",lines);mappings.add(value);
  }out.put("mappings",mappings);
  var reports=new ArrayList<Map<String,Object>>();for(var template:db.queryForList("SELECT id,report_type,name,rule_code FROM fin_report_template WHERE country_id=? AND book_id=? AND status='ACTIVE' ORDER BY report_type",a.requireCountry(),book)){
   var lines=new ArrayList<Map<String,Object>>();for(var row:db.queryForList("SELECT * FROM fin_report_template_line WHERE country_id=? AND book_id=? AND template_id=? ORDER BY seq",a.requireCountry(),book,template.get("id"))){var l=new LinkedHashMap<String,Object>();for(String key:List.of("code","name","formula","category","sign"))l.put(key,row.get(key));l.put("terms",json.read(row.get("terms").toString(),List.class));l.put("accountCodes",db.queryForList("SELECT a.code FROM fin_report_line_account r JOIN fin_account a ON a.country_id=r.country_id AND a.book_id=r.book_id AND a.id=r.account_id WHERE r.country_id=? AND r.book_id=? AND r.line_id=? ORDER BY a.code",String.class,a.requireCountry(),book,row.get("id")));lines.add(l);}var value=new LinkedHashMap<String,Object>();value.put("type",template.get("report_type"));value.put("name",template.get("name"));value.put("rule",template.get("rule_code"));value.put("lines",lines);reports.add(value);
  }out.put("reports",reports);return out;
 }
 public void apply(Access a,Map<String,Object> payload,long source){
  if(payload.values().stream().allMatch(v->v instanceof List<?> l&&l.isEmpty()))return;long book=book(a,true);
  for(var r:rows(payload,"accounts")){
   String code=Inputs.required(r,"code");Long parent=r.get("parent_code")==null?null:id(a,book,"fin_account",r.get("parent_code"));
   var existing=db.queryForList("SELECT * FROM fin_account WHERE country_id=? AND book_id=? AND code=?",a.requireCountry(),book,code);
   if(!existing.isEmpty()){for(String field:List.of("category","direction","is_leaf","fx_enabled","is_cash","is_bank","reconcile_type"))if(!Objects.equals(existing.getFirst().get(field),r.get(field)))throw new ApiException(409,"SYS_TEMPLATE_LOCAL_CONFLICT","已有本地科目与来源结构冲突，请先在科目页面复核");continue;}
   db.update("INSERT INTO fin_account(country_id,book_id,code,name,parent_id,level,category,direction,is_leaf,fx_enabled,is_cash,is_bank,aux_types,reconcile_type,status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?::jsonb,?,?)",a.requireCountry(),book,code,r.get("name"),parent,r.get("level"),r.get("category"),r.get("direction"),r.get("is_leaf"),r.get("fx_enabled"),r.get("is_cash"),r.get("is_bank"),json.write(r.get("aux_types")),r.get("reconcile_type"),r.get("status"));
  }
  for(var r:rows(payload,"cashflows"))db.update("INSERT INTO fin_cashflow_item(country_id,book_id,code,name,category,direction,status) VALUES(?,?,?,?,?,?,?) ON CONFLICT(country_id,book_id,code) DO NOTHING",a.requireCountry(),book,r.get("code"),r.get("name"),r.get("category"),r.get("direction"),r.get("status"));
  for(var r:rows(payload,"words"))db.update("INSERT INTO fin_voucher_word(country_id,book_id,code,name,number_rule,status) VALUES(?,?,?,?,?,?) ON CONFLICT(country_id,book_id,code) DO NOTHING",a.requireCountry(),book,r.get("code"),r.get("name"),r.get("number_rule"),r.get("status"));
  for(var r:rows(payload,"categoryMaps")){var category=db.queryForList("SELECT id FROM md_category WHERE code=?",Long.class,r.get("category_code"));if(category.size()!=1)throw Inputs.bad("商品分类代码不存在");db.update("INSERT INTO fin_category_account_map(country_id,book_id,category_id,purpose,account_id) VALUES(?,?,?,?,?) ON CONFLICT(country_id,book_id,category_id,purpose) DO NOTHING",a.requireCountry(),book,category.getFirst(),r.get("purpose"),id(a,book,"fin_account",r.get("account_code")));}
  for(var r:rows(payload,"mappings")){
   if(db.queryForObject("SELECT count(*) FROM fin_mapping_template WHERE country_id=? AND book_id=? AND source_template_item_id=? AND event_type=?",Integer.class,a.requireCountry(),book,source,r.get("eventType"))>0)continue;
   var normalized=new LinkedHashMap<>(r);var lines=new ArrayList<Map<String,Object>>();for(var raw:rows(r,"lines")){var l=new LinkedHashMap<>(raw);if(l.get("cashflowCode")!=null)l.put("cashflowItemId",id(a,book,"fin_cashflow_item",l.get("cashflowCode")));l.remove("cashflowCode");lines.add(l);}normalized.put("lines",lines);normalized= new LinkedHashMap<>(accounting.normalizeMapping(normalized));
   int version=db.queryForObject("SELECT coalesce(max(version_no),0)+1 FROM fin_mapping_template WHERE country_id=? AND book_id=? AND event_type=?",Integer.class,a.requireCountry(),book,r.get("eventType"));long template=db.queryForObject("INSERT INTO fin_mapping_template(country_id,book_id,event_type,version_no,accounting_mode,no_voucher_reason,source_template_item_id,created_by) VALUES(?,?,?,?,?,?,?,?) RETURNING id",Long.class,a.requireCountry(),book,r.get("eventType"),version,normalized.get("accountingMode"),normalized.get("noVoucherReason"),source,a.userId());int seq=0;
   for(var l:rows(normalized,"lines"))db.update("INSERT INTO fin_mapping_line(country_id,book_id,template_id,seq,direction,account_rule,amount_expr,aux_mapping,summary_tpl,cashflow_item_id) VALUES(?,?,?,?,?,?::jsonb,?,?::jsonb,?,?)",a.requireCountry(),book,template,++seq,l.get("direction"),json.write(l.get("accountRule")),l.get("amountExpr"),json.write(l.get("auxMapping")),l.get("summary"),l.get("cashflowItemId"));
  }
  for(var r:rows(payload,"reports")){
   if(db.queryForObject("SELECT count(*) FROM fin_report_template WHERE country_id=? AND book_id=? AND source_template_item_id=? AND report_type=?",Integer.class,a.requireCountry(),book,source,r.get("type"))>0)continue;
   var input=new ArrayList<Map<String,Object>>();for(var raw:rows(r,"lines")){var l=new LinkedHashMap<>(raw);var ids=new ArrayList<Long>();if(l.get("accountCodes") instanceof List<?> codes)for(Object code:codes)ids.add(id(a,book,"fin_account",code));l.remove("accountCodes");l.put("accountIds",ids);input.add(l);}String rule=Inputs.required(r,"rule");var lines=ReportRules.validate(rule,input);
   int version=db.queryForObject("SELECT coalesce(max(version_no),0)+1 FROM fin_report_template WHERE country_id=? AND book_id=? AND report_type=?",Integer.class,a.requireCountry(),book,r.get("type"));long template=db.queryForObject("INSERT INTO fin_report_template(country_id,book_id,report_type,name,rule_code,version_no,created_by,source_template_item_id) VALUES(?,?,?,?,?,?,?,?) RETURNING id",Long.class,a.requireCountry(),book,ReportRules.type(Inputs.required(r,"type")),r.get("name"),rule,version,a.userId(),source);int seq=0;
   for(var l:lines){long line=db.queryForObject("INSERT INTO fin_report_template_line(country_id,book_id,template_id,seq,code,name,formula,category,sign,terms) VALUES(?,?,?,?,?,?,?,?,?,?::jsonb) RETURNING id",Long.class,a.requireCountry(),book,template,++seq,l.get("code"),l.get("name"),l.get("formula"),l.get("category"),l.get("sign"),json.write(l.get("terms")));for(Object account:(List<?>)l.get("accountIds"))db.update("INSERT INTO fin_report_line_account(country_id,book_id,line_id,account_id) VALUES(?,?,?,?)",a.requireCountry(),book,line,account);}
  }
 }
 public boolean ready(Access a,long source){return db.queryForObject("SELECT (SELECT count(*) FROM fin_mapping_template WHERE country_id=? AND source_template_item_id=? AND status='NEED_REVIEW')+(SELECT count(*) FROM fin_report_template WHERE country_id=? AND source_template_item_id=? AND status='NEED_REVIEW')",Integer.class,a.requireCountry(),source,a.requireCountry(),source)==0;}
 public void confirm(Access a,long source,String comment){if(!ready(a,source))throw new ApiException(409,"SYS_CONFIG_MISSING","请先在原凭证映射和报表配置页面复核目标国版本");}
 private String code(Access a,long book,String table,long id){var values=db.queryForList("SELECT code FROM "+table+" WHERE country_id=? AND book_id=? AND id=?",String.class,a.requireCountry(),book,id);if(values.size()!=1)throw Inputs.bad("模板财务引用不存在");return values.getFirst();}
 private long id(Access a,long book,String table,Object code){var values=db.queryForList("SELECT id FROM "+table+" WHERE country_id=? AND book_id=? AND code=?",Long.class,a.requireCountry(),book,code);if(values.size()!=1)throw Inputs.bad("目标国财务代码未匹配");return values.getFirst();}
 @SuppressWarnings("unchecked") private List<Map<String,Object>> rows(Map<String,Object> payload,String key){if(!(payload.get(key) instanceof List<?> list)||list.stream().anyMatch(v->!(v instanceof Map<?,?>)))throw Inputs.bad("财务配置结构不完整");return (List<Map<String,Object>>)(List<?>)list;}
}
